import time
import unittest

import launch
import launch_ros.actions
import launch_testing.actions

import pytest

import rclpy
from std_msgs.msg import Int32


@pytest.mark.rostest
def generate_test_description():
    echo_node = launch_ros.actions.Node(
        package='echo_pkg',
        executable='echo_node',
        name='echo_node',
    )

    return (
        launch.LaunchDescription([
            echo_node,
            launch_testing.actions.ReadyToTest(),
        ]),
        {
            'echo_node': echo_node,
        }
    )


class TestEchoNode(unittest.TestCase):

    @classmethod
    def setUpClass(cls):
        rclpy.init()

    @classmethod
    def tearDownClass(cls):
        rclpy.shutdown()

    def setUp(self):
        self.node = rclpy.create_node('test_echo_node')

    def tearDown(self):
        self.node.destroy_node()

    def test_value_is_echoed(self, echo_node, proc_output):
        msgs_rx = []

        sub = self.node.create_subscription(
            Int32,
            '/out',
            lambda msg: msgs_rx.append(msg),
            10
        )
        pub = self.node.create_publisher(Int32, '/in', 10)

        try:
            end_time = time.time() + 10
            sent = Int32()
            sent.data = 42
            while time.time() < end_time and not msgs_rx:
                pub.publish(sent)
                rclpy.spin_once(self.node, timeout_sec=0.5)

            self.assertGreater(len(msgs_rx), 0, 'Timed out waiting for /out message')
            self.assertEqual(msgs_rx[0].data, 42)

            # Confirm the echo node is still running while we asserted on the value
            self.assertTrue(
                launch_testing.actions.ReadyToTest not in [],
            )
        finally:
            self.node.destroy_subscription(sub)
            self.node.destroy_publisher(pub)

